import { expect, it } from 'vitest';
import { PURSE_TRIAL } from '../index.js';
import tuning from '../data/tuning.json' with { type: 'json' };
import { validateTuning } from '../data/validate.js';

it('publishes every purse tuning key in the frozen whole-catalog view', () => {
  expect(Object.keys(PURSE_TRIAL)).toEqual([
    'marker', 'levyMaxPercent', 'levyFreePercent', 'levySatisfactionPerPoint',
    'donateSatisfactionPerGoldMilli', 'donateSatisfactionCapPerWeek',
  ]);
  expect(PURSE_TRIAL).toStrictEqual(tuning.PURSE_TRIAL);
  expect(Object.isFrozen(PURSE_TRIAL)).toBe(true);
});

it.each([
  ['levyMaxPercent', 21, 'expected 20'],
  ['levyFreePercent', 3, 'expected 2'],
  ['levySatisfactionPerPoint', 0.5, 'expected integer in [0, 100]'],
  ['donateSatisfactionPerGoldMilli', -1, 'expected number in [0, 1]'],
  ['donateSatisfactionCapPerWeek', 101, 'expected integer in [0, 100]'],
] as const)('validates %s with an exact field diagnostic', (key, value, message) => {
  const candidate = structuredClone(tuning);
  candidate.PURSE_TRIAL[key] = value;
  let error: unknown;
  try { validateTuning(candidate); } catch (caught) { error = caught; }
  expect(error).toBeInstanceOf(Error);
  expect((error as Error).message).toBe('tuning.json#PURSE_TRIAL.' + key + ': ' + message);
});

import tuningJson from '../data/tuning.json' with { type: 'json' };
import { deepFreeze, validateTuning } from '../data/validate.js';

export const PURSE_TRIAL = deepFreeze(validateTuning(tuningJson).PURSE_TRIAL);

export function levySatisfactionCost(percent: number): number {
  return Math.max(0, percent - PURSE_TRIAL.levyFreePercent) * PURSE_TRIAL.levySatisfactionPerPoint;
}

export function levyDueMilli(grossIncomeMilli: number, percent: number): number {
  return Number(BigInt(grossIncomeMilli) * BigInt(percent) / 100n);
}

export function donationSatisfaction(previousMilli: number, amountMilli: number): number {
  const { donateSatisfactionCapPerWeek: cap, donateSatisfactionPerGoldMilli: rate } = PURSE_TRIAL;
  const before = Math.min(cap, Math.floor(previousMilli * rate));
  const after = Math.min(cap, Math.floor((previousMilli + amountMilli) * rate));
  return Math.max(0, after - before);
}

import { expect, it } from 'vitest';
import {
  createCharacterLifeSession, DEFAULT_PLAYER_DRAFT, donationSatisfaction, type CharacterLifeSessionState,
} from '@haven/core';
import { executeCharacterLifeCommand } from '../character-life-command.js';
import { runLevyWeek } from '../purse-week.js';

function make() {
  const r = createCharacterLifeSession(2026, { ...structuredClone(DEFAULT_PLAYER_DRAFT), currentName: 'Keeper' });
  if (!r.success) throw Error(r.error.message);
  return r.value;
}
function dispatch(s: CharacterLifeSessionState, type: string, fields: Record<string, unknown> = {}) {
  return executeCharacterLifeCommand(s, { type, expectedRevision: s.city.revision, ...fields });
}
function act(s: CharacterLifeSessionState, type: string, fields: Record<string, unknown> = {}) {
  const r = dispatch(s, type, fields);
  if (!r.success) throw Error(type + ' ' + r.error.code);
  return r;
}
const stock = (s: CharacterLifeSessionState) => s.city.world.settlements[s.city.world.activeSettlementId!].inventory;

it.each([21, 2.5, -1, '5', Infinity])('refuses levy %s without mutation', percent => {
  const s = make(), before = structuredClone(s);
  expect(dispatch(s, 'SET_LEVY', { percent })).toMatchObject({ success: false, error: { code: 'INVALID_AMOUNT' } });
  expect(s).toStrictEqual(before);
});

it.each([[0, 'INVALID_AMOUNT'], [1500, 'INVALID_AMOUNT'], [3000, 'NOT_ENOUGH_MONEY']] as const)(
  'refuses donation %i without mutation', (amountMilli, code) => {
    const s = make(), before = structuredClone(s);
    expect(dispatch(s, 'DONATE_MONEY', { amountMilli })).toMatchObject({ success: false, error: { code } });
    expect(s).toStrictEqual(before);
  },
);

it('donates 3 Gold at 1:1 with the capped satisfaction increment and reports before resetting', () => {
  const s = make();
  s.player.purse.moneyMilli = 3000;
  const { next } = act(s, 'DONATE_MONEY', { amountMilli: 3000 });
  expect(stock(next).gold).toBe(stock(s).gold + 3000);
  expect(next.player.purse.moneyMilli).toBe(0);
  expect(next.player.purse.donatedThisWeekMilli).toBe(3000);
  for (const key of ['free', 'makers', 'luminaries', 'merchants'] as const)
    expect(next.city.society!.satisfaction[key]).toBe(Math.min(100, s.city.society!.satisfaction[key] + donationSatisfaction(0, 3000)));
  const resolved = act(next, 'END_WEEK', { expectedWeek: 1 });
  expect(resolved.report!.purse!.donationsMilli).toBe(3000);
  expect(resolved.next.player.purse.donatedThisWeekMilli).toBe(0);
});

it.each([2, 5, 10, 20])('returning the whole levy at percent %i in Money gives no direct Happiness gain', percent => {
  const initial = make(), levied = act(initial, 'SET_LEVY', { percent }).next;
  const unlevied = act(initial, 'END_WEEK', { expectedWeek: 1 }).next;
  const resolved = act(levied, 'END_WEEK', { expectedWeek: 1 }).next;
  // Exercise a wholly donatable receipt even when the seeded week's actual receipt is fractional.
  const withExactLevy = structuredClone(resolved);
  withExactLevy.player.purse.moneyMilli = 0;
  const receipt = runLevyWeek(withExactLevy, 100000).moneyAfterMilli;
  const planning = act(withExactLevy, 'NEXT_WEEK').next;
  const donated = act(planning, 'DONATE_MONEY', { amountMilli: receipt }).next;
  expect(donated.city.happiness).toBeLessThanOrEqual(unlevied.city.happiness);
});

it('keeps NPC acquisition on Gold even when the Player has Money', () => {
  const s = make();
  s.player.purse.moneyMilli = 15000;
  const guild = act(s, 'BUILD', { tileId: 'service-1', typeId: 'guild' }).next;
  const { next } = act(guild, 'BUY_NPC', { source: 'guild', slot: 0, homeTileId: 'estate-2' });
  expect(next.npcs).toHaveLength(1);
  expect(stock(next).gold).toBeLessThan(stock(guild).gold);
  expect(next.player.purse).toStrictEqual(guild.player.purse);
});

import { describe, expect, it } from 'vitest';
import {
  createCharacterLifeSession, DEFAULT_PLAYER_DRAFT, levySatisfactionCost, type DifficultyId,
} from '@haven/core';
import { executeCharacterLifeCommand } from '../character-life-command.js';
import { runLevyWeek } from '../purse-week.js';

function make(difficulty: DifficultyId = 'normal') {
  const result = createCharacterLifeSession(2026, { ...structuredClone(DEFAULT_PLAYER_DRAFT), currentName: 'Keeper' }, difficulty);
  if (!result.success) throw Error(result.error.message);
  return result.value;
}
function start(difficulty: DifficultyId = 'normal', percent = 0) {
  const s = make(difficulty);
  const command = executeCharacterLifeCommand(s, { type: 'SET_LEVY', percent, expectedRevision: s.city.revision });
  if (!command.success) throw Error(command.error.message);
  command.next.city.tiles.find(tile => tile.id === 'spec-1')!.building!.enabled = false;
  return command.next;
}
const stock = (s: ReturnType<typeof make>) => s.city.world.settlements[s.city.world.activeSettlementId!].inventory;
function close(s: ReturnType<typeof make>) {
  const r = executeCharacterLifeCommand(s, { type: 'END_WEEK', expectedWeek: s.city.world.week, expectedRevision: s.city.revision });
  if (!r.success || !r.report) throw Error('Expected End Week report');
  return { ...r, report: r.report };
}

describe('weekly levy', () => {
  it.each([['normal', 1200], ['easy', 2400]] as const)('credits %s Money on a 24 Gold gross week and charges 1.2 Gold', (difficulty, money) => {
    const s = start(difficulty, 5), r = close(s);
    const base = close(start(difficulty));
    expect(r.report.taxMilli + r.report.goods.revenueMilli + r.report.laws!.incomeMilli).toBe(24000);
    expect(r.report.purse).toEqual({ levyPercent: 5, levyDueMilli: 1200, levyPaidMilli: 1200, donationsMilli: 0, moneyAfterMilli: money });
    expect(stock(r.next).gold).toBe(stock(base.next).gold - 1200);
    expect(r.report.after.gold).toBe(stock(r.next).gold);
    expect(r.next.player.purse.moneyMilli).toBe(money);
    expect(close(structuredClone(s))).toEqual(r);
  });

  it.each([['normal', 400], ['easy', 800]] as const)('caps the Gold charge at 0.4 in %s and reports a 0.8 shortfall', (difficulty, money) => {
    const s = start(difficulty, 5);
    stock(s).gold = 400;
    const report = runLevyWeek(s, 24000);
    expect(report.levyDueMilli - report.levyPaidMilli).toBe(800);
    expect(report.levyPaidMilli).toBe(400);
    expect(stock(s).gold).toBe(0);
    expect(s.player.purse.moneyMilli).toBe(money);
  });

  it('floors gross levy before scaling Money', () => {
    const s = start('easy', 5);
    expect(runLevyWeek(s, 24019)).toMatchObject({ levyDueMilli: 1200, levyPaidMilli: 1200, moneyAfterMilli: 2400 });
  });

  it.each([0, 1, 2, 3])('applies the levy at percent %i penalty to citizens before the Happiness report', percent => {
    const base = close(start()), r = close(start('normal', percent));
    const scores = r.next.city.society!.satisfaction;
    const baseline = base.next.city.society!.satisfaction;
    for (const group of ['free', 'makers', 'luminaries', 'merchants'] as const) {
      expect(scores[group]).toBe(baseline[group] - levySatisfactionCost(percent));
      expect(r.report.society!.classes[group].satisfactionAfter).toBe(scores[group]);
    }
    expect(scores.bound).toBe(baseline.bound);
    expect(r.report.happinessAfter).toBe(r.next.city.happiness);
    expect(r.report.happinessAfter).toBe(Number((base.report.happinessAfter - levySatisfactionCost(percent)).toFixed(2)));
  });

  it('keeps the purse with the Player when the active pointer moves to a new city', () => {
    const s = start('normal', 5), world = s.city.world;
    const previous = world.settlements[world.activeSettlementId!];
    s.player.purse.moneyMilli = 9000;
    world.settlements.alternate = { ...structuredClone(previous), id: 'alternate' };
    previous.status = 'legacy';
    world.activeSettlementId = 'alternate';
    const r = close(s);
    expect(r.next.player.purse.moneyMilli).toBe(10200);
    expect(r.next.city.world.settlements[previous.id]).toEqual(previous);
    expect(Object.hasOwn(r.next.city.world.settlements[previous.id], 'purse')).toBe(false);
    expect(r.next.city.world.activeSettlementId).toBe('alternate');
  });
});

import {
  donationSatisfaction, hasWeeklyKeys, isLiveCharacterLifeSessionState, PURSE_TRIAL,
  type CharacterLifeSessionState,
} from '@haven/core';
import type { CharacterLifeCommandResult } from './character-life-command.js';
import { cityHappiness, societyCounts } from './society-week.js';

export const PURSE_COMMAND_TYPES = ['SET_LEVY', 'DONATE_MONEY'] as const;
export type PurseCommandType = typeof PURSE_COMMAND_TYPES[number];

const fields: Record<PurseCommandType, string> = { SET_LEVY: 'percent', DONATE_MONEY: 'amountMilli' };
const fail = (code: string, message: string): CharacterLifeCommandResult => ({ success: false, error: { code, message } });
const whole = (n: unknown): n is number => typeof n === 'number' && Number.isSafeInteger(n);

export function executePurseCommand(
  session: CharacterLifeSessionState, type: PurseCommandType, raw: unknown,
): CharacterLifeCommandResult {
  if (session.city.phase !== 'planning')
    return fail('FORBIDDEN', 'Plan next week before changing the purse.');
  if (!hasWeeklyKeys(raw, ['type', 'expectedRevision', fields[type]]))
    return fail('INVALID_COMMAND', 'Command must contain plain data fields.');
  if (raw.expectedRevision !== session.city.revision)
    return fail('STALE_COMMAND', 'The purse changed. Try again.');

  const next = structuredClone(session);
  const purse = next.player.purse;
  if (type === 'SET_LEVY') {
    const percent = raw.percent;
    if (!whole(percent) || percent < 0 || percent > PURSE_TRIAL.levyMaxPercent)
      return fail('INVALID_AMOUNT', 'Enter a whole levy percent from 0 to ' + PURSE_TRIAL.levyMaxPercent + '.');
    purse.levyPercent = percent === 0 ? 0 : percent;
  } else {
    const amount = raw.amountMilli;
    if (!whole(amount) || amount <= 0 || amount % 1000 !== 0)
      return fail('INVALID_AMOUNT', 'Enter a positive whole amount.');
    if (amount > purse.moneyMilli) return fail('NOT_ENOUGH_MONEY', 'Not enough Money.');
    const { world, society } = next.city;
    const stock = world.settlements[world.activeSettlementId!].inventory;
    if (!whole(stock.gold + amount) || !whole(purse.donatedThisWeekMilli + amount))
      return fail('INVALID_AMOUNT', 'This donation is too large.');
    const bonus = donationSatisfaction(purse.donatedThisWeekMilli, amount);
    if (bonus > 0) {
      for (const key of ['free', 'makers', 'luminaries', 'merchants'] as const) {
        society!.satisfaction[key] = Math.min(100, society!.satisfaction[key] + bonus);
      }
      next.city.happiness = cityHappiness(society!.satisfaction, societyCounts(society!), next.city.happiness);
    }
    purse.moneyMilli -= amount;
    stock.gold += amount;
    purse.donatedThisWeekMilli += amount;
  }
  next.city.revision++;
  if (!isLiveCharacterLifeSessionState(next))
    return fail('EXECUTION_ERROR', 'The action failed validation; the original session was preserved.');
  return { success: true, next };
}

import {
  applyDifficulty, difficultyProfile, levyDueMilli, type CharacterLifeSessionState, type PurseWeekReport,
} from '@haven/core';
import { trialSafe } from './workshop-operation.js';

export function runLevyWeek(session: CharacterLifeSessionState, grossIncomeMilli: number): Readonly<PurseWeekReport> {
  const purse = session.player.purse;
  const { world, society } = session.city;
  const stock = world.settlements[world.activeSettlementId!].inventory;
  const due = purse.levyPercent === 0 ? 0 : levyDueMilli(trialSafe(grossIncomeMilli), purse.levyPercent);
  const paid = Math.min(stock.gold, due);
  const money = applyDifficulty(paid, difficultyProfile(society!.difficulty).levyMoneyBps);
  const moneyAfterMilli = trialSafe(purse.moneyMilli + money);
  stock.gold -= paid;
  purse.moneyMilli = moneyAfterMilli;
  return Object.freeze({
    levyPercent: purse.levyPercent, levyDueMilli: due, levyPaidMilli: paid,
    donationsMilli: purse.donatedThisWeekMilli, moneyAfterMilli,
  });
}

import { expect, it } from 'vitest';
import { parseDonationMilli, purseControls } from '../purse-view.js';
import { purseReportRows } from '../report-letters.js';
import { itemError } from '../items-view.js';

it.each(['', '0', ' 2', '2 ', '+2', '2.0', '1e2', '2x', '9007199254741'])('rejects donation input %j', input => {
  expect(parseDonationMilli(input)).toBeNull();
});

it('parses whole digits and explains all disabled purse actions', () => {
  const purse = { levyPercent: 0, donatedThisWeekMilli: 0, moneyMilli: 3000, robbery: null };
  expect(parseDonationMilli('03')).toBe(3000);
  expect(purseControls(purse, '3', false)).toMatchObject({
    decreaseReason: 'Weekly levy is at its minimum.', increaseReason: '', donateReason: '', happinessCost: 0,
  });
  expect(purseControls({ ...purse, levyPercent: 20 }, '4', false)).toMatchObject({
    increaseReason: 'Weekly levy is at its maximum.', donateReason: 'Not enough Money.',
  });
  expect(purseControls(purse, '3', true)).toMatchObject({
    decreaseReason: 'Plan next week before changing the purse.',
    increaseReason: 'Plan next week before changing the purse.',
    donateReason: 'Plan next week before changing the purse.',
  });
  expect(itemError('NOT_ENOUGH_MONEY')).toBe('Not enough Money.');
});

it('shows both purse transactions and the shortfall in the report', () => {
  const purse = { levyPercent: 5, levyDueMilli: 1200, levyPaidMilli: 400, donationsMilli: 3000, moneyAfterMilli: 400 };
  expect(purseReportRows(purse, 'normal')).toEqual([
    { label: 'Levy', value: '+0.4 Money · 5% · 0.4 of 1.2 Gold paid · 0.8 Gold shortfall' },
    { label: 'Donation', value: '−3 Money' },
    { label: 'Money after', value: '0.4 Money' },
  ]);
  expect(purseReportRows({ ...purse, moneyAfterMilli: 800 }, 'easy')[0].value).toBe(
    '+0.8 Money · 5% · 0.4 of 1.2 Gold paid · 0.8 Gold shortfall',
  );
});

import { levySatisfactionCost, PURSE_TRIAL, type PlayerCharacter } from '@haven/core';

export function parseDonationMilli(text: string): number | null {
  if (!/^[0-9]+$/.test(text)) return null;
  const amountMilli = Number(text) * 1000;
  return Number.isSafeInteger(amountMilli) && amountMilli > 0 ? amountMilli : null;
}

export function purseControls(purse: PlayerCharacter['purse'], input: string, locked: boolean) {
  const amountMilli = parseDonationMilli(input);
  const lockReason = locked ? 'Plan next week before changing the purse.' : '';
  return {
    amountMilli,
    happinessCost: levySatisfactionCost(purse.levyPercent),
    decreaseReason: lockReason || (purse.levyPercent === 0 ? 'Weekly levy is at its minimum.' : ''),
    increaseReason: lockReason || (purse.levyPercent === PURSE_TRIAL.levyMaxPercent ? 'Weekly levy is at its maximum.' : ''),
    donateReason: lockReason || (amountMilli === null ? 'Enter a positive whole amount.' :
      amountMilli > purse.moneyMilli ? 'Not enough Money.' : ''),
  };
}

import { expect, test } from '@playwright/test';
import { executeCharacterLifeCommand } from '@haven/simulation';
import { expectReport, exportLife, go, importLife, keyActivate, makeLife, tabTo } from './character-life-navigation.helpers.ts';

for (const width of [1280, 1600]) {
  test('uses the Player purse, reports both transactions and round-trips at ' + width, async ({ page }) => {
    await page.setViewportSize({ width, height: 900 });
    const s = makeLife();
    s.player.purse.moneyMilli = 3000;
    await page.goto('/');
    await importLife(page, s);
    await expect(page.getByTestId('purse-money')).toHaveText('Money 3');
    const player = page.locator('#life-nav-player');
    await tabTo(page, player);
    await keyActivate(page, player);
    const purse = page.getByRole('region', { name: 'Purse', exact: true });
    await expect(purse).toContainText('Safe amount — · At risk —');
    await expect(purse.getByRole('button', { name: 'Decrease weekly levy' })).toHaveAttribute('aria-disabled', 'true');
    const increase = purse.getByRole('button', { name: 'Increase weekly levy' });
    await tabTo(page, increase);
    for (let i = 0; i < 5; i++) await keyActivate(page, increase);
    await expect(purse).toContainText('5 %');
    const input = purse.getByLabel('Donation amount in Gold');
    await tabTo(page, input);
    await page.keyboard.type('1e2');
    await expect(purse.getByRole('button', { name: 'Donate', exact: true })).toHaveAttribute('aria-disabled', 'true');
    await input.fill('4');
    await expect(purse).toContainText('Not enough Money.');
    await input.fill('1');
    const donate = purse.getByRole('button', { name: 'Donate', exact: true });
    await tabTo(page, donate);
    await keyActivate(page, donate);
    await expect(purse).toContainText('Money 2');
    await page.keyboard.press('Escape');
    await expect(player).toBeFocused();

    const before = await exportLife(page);
    expect(before.player.purse).toMatchObject({ moneyMilli: 2000, levyPercent: 5, donatedThisWeekMilli: 1000 });
    await go(page, 'session');
    await page.getByRole('button', { name: 'Save locally', exact: true }).click();
    await expect(page.getByText('Saved in this browser.', { exact: true })).toBeVisible();
    await page.reload();
    await page.getByRole('button', { name: 'Continue', exact: true }).click();
    await expect(page.getByTestId('life-shell')).toBeVisible();
    expect((await exportLife(page)).player.purse).toStrictEqual(before.player.purse);
    await importLife(page, before);
    const planning = await exportLife(page);
    expect(planning.player.purse).toStrictEqual(before.player.purse);

    const r = executeCharacterLifeCommand(planning, { type: 'END_WEEK', expectedWeek: 1, expectedRevision: planning.city.revision });
    if (!r.success || !r.report) throw Error('Expected End Week report');
    await go(page, 'city');
    await page.getByTestId('life-end-week').click();
    expect((await expectReport(page, r.report)).purse).toStrictEqual(r.report.purse);
    expect(r.report.purse?.donationsMilli).toBe(1000);
  });
}
